      "replacement": "            if (byte_accepted)
            begin
                r_byte <= i_byte[7:0];
                r_state <= LLSDSPI_START;
                r_idle <= 1'b0;
                o_mosi <= i_byte[7];
                o_sclk <= 1'b1;
            end else"
